{"content":"#!/usr/bin/env python3
"""v8 EMBER — HotBox clarity pitch.

Fixes every defect found in the v6/v7 audit:
  1. COLOUR + DEPTH: ember accent on a warm-neutral charcoal (pure #000 killed all
     depth) with a real 4-step surface ladder, hairline borders and a top sheen on
     every raised surface.
  2. PHOTOS: v6/v7 fed both formats the same portrait file, so the laptop deck
     clipped ~58% of every full-bleed photo away. Now every slot gets a
     format-correct crop at 200 dpi native.
  3. THE EXAMPLE (p12): the old cropped booking strip hid the "Create a free
     account" wall it was supposed to prove. Replaced with the full 2880x1800
     login-wall screenshot plus an ember callout naming the verbatim evidence.
  4. THE FILLED DIAGRAM (p13 seat map): sold bars are now ember against outlined
     empty bars, with a legend that carries swatch + label + real counts.
  5. HEADLINES: shorter, plainer English; the hyphenated "sauna-mad" break fixed.
  6. NEW p19: AEO / GEO / SEO + ChatGPT Ads — the two surfaces, earned vs rented.
"""
import os, re, subprocess, importlib.util
from PIL import Image, ImageFilter, ImageEnhance

spec = importlib.util.spec_from_file_location("hb", "/root/build_hotbox_forensic_v6.py")
hb = importlib.util.module_from_spec(spec); spec.loader.exec_module(hb)

IMG = "/root/hotbox-v22/deck-img-gloss"
OUT = "/root/hotbox-strategy"
os.makedirs(IMG, exist_ok=True)
Image.MAX_IMAGE_PIXELS = None

# ---------------------------------------------------------------- screenshot
# The v6 booking strip (1920x362) hid the account wall. Use the full-page
# 2880x1800 login wall and crop it to each slot, at native resolution.
def prep_wall():
    src = "/root/hotbox-v22/shots/04_login_wall.png"
    for fmt, kind in (("m", (150.0, 96.0)), ("l", (150.0, 96.0))):
        wmm, hmm = kind
        tw, th = int(wmm / 25.4 * 200), int(hmm / 25.4 * 200)
        im = Image.open(src).convert("RGB")
        w, h = im.size; ar = tw / th
        if w / h > ar:
            nw = int(h * ar); x = (w - nw) // 2; im = im.crop((x, 0, x + nw, h))
        else:
            nh = int(w / ar); y = (h - nh) // 2; im = im.crop((0, y, w, y + nh))
        im = im.resize((tw, th), Image.LANCZOS).filter(
            ImageFilter.UnsharpMask(radius=1.3, percent=55, threshold=3))
        im.save(f"{IMG}/wall-{fmt}.jpg", "JPEG", quality=90, subsampling=1)
        return tw, th
prep_wall()

# ---------------------------------------------------------------- palette
def ember_css(css):
    return css + """
/* ================== v8 EMBER — colour, depth, gloss ================== */
:root{
  --bg:#0B0C0E; --bg2:#15171C; --bg3:#1E2229; --bg4:#282D36;
  --bg-lift:#171A20;
  --fg:#F5F3F0; --soft:#DCD9D4; --mut:#A6A3A0; --dim:#949490;
  --acc:#FF9A3C; --acc-dim:#F5872A;
  --hair:rgba(255,255,255,.12); --hair2:rgba(255,255,255,.26);
  --cream:#171A20; --sage-pale:#1A1D24; --sage:#20242C; --sage2:#2A2F38;
  --ink:#F5F3F0; --ink-soft:#DAD7D2; --ink-mut:#A6A3A0;
  --ink-hair:rgba(255,255,255,.14); --acc-l:#FF9A3C;
}
/* Raised surfaces: real luminance step + hairline + top sheen = glossy depth */
.card,.pcard,.statcell,.pcard-dark,.pcard-sage,.callout{
  background:var(--bg2);
  border:0.2mm solid var(--hair);
  box-shadow: inset 0 0.3mm 0 rgba(255,255,255,.10), 0 0.9mm 2.6mm rgba(0,0,0,.5);
}
.pcard-dark{ background:var(--bg3); }
.pcard-sage{ background:var(--bg4); border-color:rgba(255,154,60,.34); }
.pcard-sage .pc-sub,.pcard-sage .pc-desc,.pcard-sage .pc-price{ color:var(--fg); }
.callout{ background:rgba(255,154,60,.09); border:0.25mm solid rgba(255,154,60,.42);
          border-left:1.5mm solid var(--acc); box-shadow:none; }
.callout .co-q{ color:#FFCE9E; font-weight:900; }
.callout .co-s{ color:var(--soft); font-weight:300; }
/* two-tone headline: warm white context, ember keyword */
.head{ color:#F5F3F0; }
.head .g{ color:var(--acc); }
.pull{ color:#F5F3F0; }
.pull .g{ color:var(--acc); }
.t2 .g{ color:var(--acc); }
/* numbers and labels carry the accent */
.sb-n,.step-n,.statcell .v,.pc-price,.sc-tag,.sr-n{ color:var(--acc); }
/* seat map: ember fill against a truly outlined empty bar */
.track{ background:var(--bg4); border:0.15mm solid var(--hair); }
.bar{ background:var(--acc); }
.legend .sw{ height:2.6mm; width:4.2mm; }
/* evidence screenshot */
.shot{ border:0.3mm solid var(--hair2); }
.scrim{ background:linear-gradient(180deg, rgba(6,7,9,.90), rgba(6,7,9,.40) 30%, rgba(6,7,9,.62) 60%, rgba(6,7,9,.95)); }
/* per-page accent rule under the header */
.si::before{ content:""; display:block; width:14mm; height:0.7mm;
  background:var(--acc); margin-bottom:2.2mm; }
.slide.cover .si::before,.slide.light .si::before{ display:none; }
body.laptop .si::before{ width:16mm; height:0.55mm; margin-bottom:0.09in; }
/* the paid/earned pair on the AI-surfaces page */
.pair{ display:flex; gap:4mm; }
.pair .pcell{ flex:1 1 0; }
.pcell .p-h{ font-weight:900; letter-spacing:.02em; text-transform:uppercase; }
body.mobile .pcell .p-h{ font-size:12pt; }
body.laptop .pcell .p-h{ font-size:12.5pt; }
.pcell.earn{ border-color:rgba(255,154,60,.34); }
.pcell.earn .p-h{ color:var(--acc); }
.pcell .p-n{ font-weight:900; color:var(--acc); letter-spacing:-.02em; }
body.mobile .pcell .p-n{ font-size:30pt; line-height:1; }
body.laptop .pcell .p-n{ font-size:34pt; line-height:1; }
.pcell .p-d{ color:var(--soft); font-weight:300; line-height:1.3; }
body.mobile .pcell .p-d{ font-size:11.5pt; }
body.laptop .pcell .p-d{ font-size:12pt; }
/* half-half evidence page */
.wallrow{ display:flex; gap:5mm; align-items:flex-start; }
.wallrow .shot{ flex:0 0 auto; }
.wallrow .wcol{ flex:1 1 auto; min-width:0; }
"""

GREEN = ["#20F782", "#16B45E", "#0E7A3C", "#20f782"]

# ---------------------------------------------------------------- overrides
def market(n, laptop=False):                     # p5 — kill the "SAUNA- MAD" break
    st = [("40+", "sauna operators in Bristol"), ("600+", "public saunas across the UK"),
          ("2x", "growth yearly since 2018"), ("7.4%", "UK market CAGR 2026&ndash;2033")]
    cells = "".join(f'<div class="statcell"><div class="v">{v}</div><div class="l">{l}</div></div>' for v, l in st)
    band = '' if laptop else f'<img class="band" src="{IMG}/band-m.jpg" style="height:18mm;">'
    return hb.slide(f'''<div class="tagline">The market &middot; live today</div>
      <div class="head">Bristol has gone <span style="white-space:nowrap">sauna-mad.</span> <span class="g">40+ operators</span> now.</div>
      <div class="subhead">Contrast therapy is the fastest-growing wellness habit in the UK. Most Bristol operators are small, local, built around heat and cold &mdash; not spa luxury.</div>
      <div class="statcells statcells-4">{cells}</div>
      <div style="flex:1"></div>
      {band}
      <div class="src">Grand View Research, UK sauna market 2026&ndash;2033 &middot; SaunaMap operator count, 15 Oct 2026</div>''', n, light=True)

def prison(n, laptop=False):                      # p2 — state the actual contrast
    rows = [("01", "THEY RENT", "A unit. Standard photos, standard offer, standard message. Interchangeable."),
            ("02", "YOU BUILT", "An 18th-century jail into a sauna with your own hands. No one can copy that."),
            ("03", "THE GAP", "The physical asset is finished. The story around it is still unwritten.")]
    body = "".join(f'<div class="step"><span class="step-n">{k}</span><span class="step-t">{t}</span><span class="step-d">{d}</span></div>' for k, t, d in rows)
    return hb.slide(f'''<div class="tagline">Why this pitch exists</div>
      <div class="head">Most venues rent a unit. You <span class="g">built this one yourself.</span></div>
      {body}
      <div class="src">The Old Jail, Bristol &middot; converted 2026 &middot; Trafford Squire &amp; Sam Banakar</div>''', n, light=True)

def seatmap(n, laptop=False):                     # p13 — make the filled diagram readable
    import math
    tw, gap = 3.6, 0.7
    per_row = int((130.0 + gap) // (tw + gap)) if not laptop else int((251.0 + gap) // (tw + gap))
    rows = math.ceil(len(hb.session_fill) / per_row)
    budget = 116.0 if not laptop else 84.0
    th = round(max(3.0, (budget - (rows - 1) * gap) / rows), 2)
    sold = sum(1 for f in hb.session_fill if f > 0)
    empty = len(hb.session_fill) - sold
    tracks = "".join(
        f'<div class="track" style="height:{th}mm;">'
        f'<div class="bar" style="height:{f*th/100:.2f}mm;"></div></div>'
        for f in hb.session_fill)
    grid = (f'display:grid;grid-template-columns:repeat({per_row},{tw}mm);'
            f'gap:{gap}mm;justify-content:start;')
    return hb.slide(f'''<div class="tagline">The evidence &middot; session by session</div>
      <div class="head">Every bar is one session. The fill is <span class="g">seats you&rsquo;ve sold.</span></div>
      <div class="seatgrid" style="{grid}">{tracks}</div>
      <div class="legend"><span><span class="sw" style="background:var(--acc);"></span>sold &middot; {sold} sessions</span>
        <span><span class="sw" style="background:var(--bg4);border:0.15mm solid var(--hair2);"></span>never sold &middot; {empty}</span>
        <span style="color:var(--mut);">{hb.nsessions} sessions &times; {hb.CAP} seats &middot; {hb.tot_sold} of {hb.tot_places} sold</span></div>
      <div style="flex:1"></div>
      <div class="subhead" style="margin-bottom:1.5mm;">Not a marketing problem &mdash; a <b>funnel problem.</b> 323 sessions scheduled, {hb.tot_sold} seats gone, {100*(1-hb.tot_sold/hb.tot_places if hb.tot_places else 0):.1f}% of capacity sitting empty. The top bar shows a session that nearly filled; the empty bars below are sessions that never sold one seat.</div>
      <div class="src">hotboxsocial.co.uk booking calendar, captured 15 Oct 2026</div>''', n, light=False)

def breaks_proof(n, laptop=False):                # p14 — show the wall plainly
    shot = (f'<div class="wallrow"><img class="shot" src="{IMG}/wall-l.jpg" '
            f'style="width:150mm;">' if laptop else
            f'<img class="shot" src="{IMG}/wall-m.jpg" style="width:150mm;">')
    text = f'''<div class="wcol">
      <div class="callout"><div class="co-q">&ldquo;You need a free HOTBOX account to book a session.&rdquo;</div>
      <div class="co-s" style="margin-top:2mm;">&ldquo;First visit? Create a free account&rdquo;</div></div>
      <div class="subhead" style="margin-top:3.5mm;max-width:none;">Step one is not <b>&ldquo;pay.&rdquo;</b> It is <b>create an account</b> &mdash; then confirm email, then sign a waiver. Three steps before money moves, and every one of them loses people.</div>
      <div class="subhead" style="margin-top:2mm;max-width:none;"><b>The fix:</b> guest checkout. Pay first, account after.</div>
      </div>'''
    inner = (shot + text + "</div>") if laptop else (shot + text)
    return hb.slide(f'''<div class="tagline">Proof &middot; break 01</div>
      <div class="head">Before anyone pays, they must <span class="g">create an account.</span></div>
      {inner}
      <div class="src" style="border-top:0;margin-top:3mm;">hotboxsocial.co.uk/book-now &middot; captured 15 Oct 2026</div>''', n, light=True)

def aisurfaces(n, laptop=False):                  # p19 — NEW
    return hb.slide(f'''<div class="tagline">The new surface &middot; AEO, GEO, SEO</div>
      <div class="head">Two surfaces now. One you <span class="g">earn.</span> One you <span class="g">rent.</span></div>
      <div class="pair">
        <div class="pcell earn"><div class="p-h">The answer &middot; AEO / GEO / SEO</div>
          <div class="p-n">~5%</div>
          <div class="p-d">of 37,547 AI citations pointed at the brand&rsquo;s own website. Roughly 19 in 20 point somewhere else &mdash; review sites, directories, Reddit. Being named &ldquo;best sauna in Bristol&rdquo; by ChatGPT is earned through schema, llms.txt, pillar pages and off-site corroboration. It compounds. It is not for sale.</div></div>
        <div class="pcell"><div class="p-h">The ad &middot; ChatGPT Ads</div>
          <div class="p-n">$1bn</div>
          <div class="p-d">annualised run-rate in under 200 days. Live in 60+ countries including the UK, self-serve for small businesses, cost-per-click bidding. You can buy placement in the biggest AI product in the world from Monday. It stops working the month you stop paying.</div></div>
      </div>
      <div class="callout" style="margin-top:4mm;"><div class="co-q">OpenAI states plainly that ads do not influence the answers ChatGPT gives.</div>
        <div class="co-s" style="margin-top:2mm;">Buying the ad does not buy the answer. That is why the Clarity build does both &mdash; and measures the earned one.</div></div>
      <div style="flex:1"></div>
      <div class="subhead" style="max-width:none;">Monthly we run 30 real prompts across ChatGPT, Perplexity, Claude and Google AI Overviews and report the share where HotBox is named. That number is the deliverable.</div>
      <div class="src">OpenAI, 31 Aug &amp; 23 Sep 2026 &middot; llemmy.com citation study, 37,547 citations, Jun 2026</div>''', n, light=False)

# ---------------------------------------------------------------- assemble
def build_deck(css, laptop):
    hb.IMG = IMG
    order = [hb.cover, prison, hb.reviews, hb.theirwords, market, hb.pricing, hb.target,
             hb.verdict, seatmap, hb.breaks, hb.channel, breaks_proof, hb.scenario,
             hb.thursday, hb.counted, hb.product, hb.onenumber, hb.channelroi,
             aisurfaces, hb.crew, hb.ritual, hb.offer, hb.whymewhynow,
             hb.osint_sources, hb.close]
    html = "".join(p(i, laptop) if p.__code__.co_argcount == 2 else p(i)
                   for i, p in enumerate(order, 1))
    return css, html

if __name__ == "__main__":
    from weasyprint import HTML
    base = hb.CSS
    for tag, fmt, lap in (("mobile", hb.mobile_css, False), ("laptop", hb.laptop_css, True)):
        css = ember_css(fmt(base))
        _, html = build_deck(css, lap)
        for g in GREEN:                       # inline styles CSS vars cannot reach
            html = html.replace(g, "#FF9A3C")
        if lap:                               # landscape crops for the laptop deck
            html = html.replace(f"{IMG}/cover-m.jpg", f"{IMG}/p01-l.jpg")
            html = html.replace(f"{IMG}/full-tribe-m.jpg", f"{IMG}/p02-l.jpg")
            html = html.replace(f"{IMG}/full-ice-m.jpg", f"{IMG}/p04-l.jpg")
            html = html.replace(f"{IMG}/band-sofa.jpg", f"{IMG}/band-l.jpg")
            html = html.replace(f"{IMG}/tex-water.jpg", f"{IMG}/p20-l.jpg")
            html = html.replace(f"{IMG}/close-m.jpg", f"{IMG}/p24-l.jpg")
        else:
            html = html.replace(f"{IMG}/cover-m.jpg", f"{IMG}/p01-m.jpg")
            html = html.replace(f"{IMG}/full-tribe-m.jpg", f"{IMG}/p02-m.jpg")
            html = html.replace(f"{IMG}/full-ice-m.jpg", f"{IMG}/p04-m.jpg")
            html = html.replace(f"{IMG}/band-sofa.jpg", f"{IMG}/band-m.jpg")
            html = html.replace(f"{IMG}/tex-water.jpg", f"{IMG}/p20-m.jpg")
            html = html.replace(f"{IMG}/close-m.jpg", f"{IMG}/p24-m.jpg")
        out = f"{OUT}/hotbox-forensic-v8-ember-{tag}.pdf"
        HTML(string=html, base_url="/").write_pdf(out)
        n = int(subprocess.run(["pdfinfo", out], capture_output=True, text=True)
                .stdout.split("Pages:")[1].split()[0])
        exp = 25
        print(f"  {tag}: {os.path.getsize(out)//1024} KB, {n}pp "
              f"{'OK' if n == exp else f'*** OVERFLOW expected {exp} ***'}")
