{"content":"#!/usr/bin/env python3
"""v9 CLARITY — HotBox pitch, built from scratch.

Why a rebuild: v8 still put a tagline, a rule, a headline, a subhead, a four-cell
stat grid, a photo, a second subhead and a source line on one page. That is a data
report, not a pitch — eight elements compete and nothing lands.

New rules, applied as constraints rather than finished with a filter:
  1. At most THREE text elements per page: one headline, one caption, one label.
     No second paragraph. No stat grids. A number that matters gets its own page
     at display size instead of sitting in a box beside three others.
  2. No source lines on the pitch pages. One sources page at the back.
  3. The headline is the page. Type goes much larger.
  4. Colour is a FIELD, not trim. Ember blocks and full ember pages carry real area
     so the palette reads as a system rather than an accent at 2% coverage.
  5. One photo per page, full-bleed or half-bleed, 200 dpi, using the venue's own
     high-res assets (3840px-wide originals from hotboxsocial.co.uk).
"""
import os, math, subprocess
from PIL import Image, ImageFilter, ImageEnhance

try:
    import numpy as np
except ImportError:
    np = None
from weasyprint import HTML

SRC = "/root/hotbox-v22/newimg"
IMG = "/root/hotbox-v22/deck-v9"
OUT = "/root/hotbox-strategy"
os.makedirs(IMG, exist_ok=True)
Image.MAX_IMAGE_PIXELS = None
MM, DPI = 25.4, 200

# ---------------------------------------------------------------- assets
def fill(im, ar):
    w, h = im.size
    if w / h > ar:
        nw = int(h * ar); x = (w - nw) // 2; return im.crop((x, 0, x + nw, h))
    nh = int(w / ar); y = (h - nh) // 2; return im.crop((0, y, w, y + nh))

def px(wmm, hmm):
    return int(wmm / MM * DPI), int(hmm / MM * DPI)

def save(im, tw, th, name):
    im = im.resize((tw, th), Image.LANCZOS).filter(
        ImageFilter.UnsharpMask(radius=1.3, percent=55, threshold=3))
    im = ImageEnhance.Contrast(im).enhance(1.05)
    p = os.path.join(IMG, name)
    im.convert("RGB").save(p, "JPEG", quality=88, subsampling=1)
    return p, os.path.getsize(p) // 1024

# page -> (portrait source, landscape source)
PHOTOS = {
    1:  ("hotbox-62.jpg",  "hotbox-13.jpg"),   # cover: the ice baths
